#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/dprint/tasks/setup-dprint.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Upgrade dprint plugins"
# MISE hide=true
# MISE tools={uv="latest", python="3.14", dprint="latest"}

import os
import shutil
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def main():
  helpers.print_header("Updating dprint plugins ...")

  # The plugins of the shared dprint.jsonc of this repository. The sync finds a
  # plugin by its name, so the new version stays at the next sync.
  os.chdir(os.environ["MISE_PROJECT_ROOT"])
  # The # MISE tools line gives dprint in every repository, so the task calls
  # it directly. Without it, the task stops as the shell does for a missing
  # command.
  dprint = shutil.which("dprint")
  if dprint is None:
    print("dprint: command not found", file=sys.stderr, flush=True)
    return 127
  return subprocess.run([dprint, "config", "update", "--yes"], check=False).returncode


if __name__ == "__main__":
  sys.exit(main())
